import { LogOut } from "lucide-react";
import { Link } from "react-router-dom";

export default function ChatSidebar({
	themeMode,
	setThemeMode,
	isLight,
	theme,
	location,
	navigate,
	ROUTES,
	CHAT_NAV_ITEMS,
	totalUnread,
}) {
	return (
		<aside
			class="hidden md:flex h-full rounded-[22px] p-2 flex-col items-center justify-between py-1"
			style={{ background: "transparent", boxShadow: "none" }}
		>
			<div class="space-y-2">
				<button
					class={`mb-4 flex h-10 w-10 items-center justify-center rounded-[12px] shadow-none text-lg transition-colors${
						isLight
							? "bg-white text-orange-400 shadow-sm"
							: "bg-[var(--theme-custom-171031)] text-[var(--theme-custom-d4ff59)]"
					}`}
					onClick={() => setThemeMode((value) => (value === "light" ? "dark" : "light"))}
					title={isLight ? "Switch to Dark Mode" : "Switch to Light Mode"}
				>
					{isLight ? "☀️" : "🌙"}
				</button>
				{CHAT_NAV_ITEMS.map((item) => {
					const Icon = item.icon;
					const isActive = location.pathname === item.to;
					const showBadge = item.label === "Chat" && totalUnread > 0;
					return (
						<Link
							key={item.to}
							to={item.to}
							class={`relative flex h-10 w-10 items-center justify-center rounded-[12px] transition-all${
								isActive
									? isLight
										? "bg-gtBlue text-white"
										: "bg-[var(--theme-custom-0a66c2-18)] text-[var(--theme-custom-d4ff59)]"
									: isLight
										? "text-slate-400 hover:bg-white hover:text-gtBlue"
										: "bg-[var(--theme-custom-171031)] text-[var(--theme-custom-8f95bb)] hover:text-white"
							}`}
							title={item.label}
						>
							<Icon size={18} strokeWidth={1.5} />
							{showBadge ? (
								<span class="absolute -top-1 -right-1 flex h-4 min-w-[16px] items-center justify-center rounded-full bg-red-500 px-1 text-[9px] font-bold text-white">
									{totalUnread > 99 ? "99+" : totalUnread}
								</span>
							) : null}
						</Link>
					);
				})}
			</div>
			<button
				class="flex h-10 w-10 items-center justify-center rounded-[12px] transition-colors"
				style={{
					background: isLight ? "#ffffff" : theme.tileBg,
					color: isLight ? "#ef4444" : "#8f95bb",
				}}
				onClick={() => navigate(ROUTES.LOGIN)}
				title="Logout"
			>
				<LogOut size={18} strokeWidth={1.5} />
			</button>
		</aside>
	);
}
